if (!this.isRoot) { this.picked(id); this.close(); return }
this.close()
this.$afterDelay(0, () => this.picked(id))

const o = (row).rootOrigin()
if (this.child == null) this.child = this.root.createView("Menu", ({ isRoot: false, rootMenu: this.rootMenu != null ? this.rootMenu : this }))
this.driveSub(this.child, subItems, o.x + this.width - 6, o.y - 5)

const rows = this.rowsOf(this.panel.body).filter((r) => !r.divider && r.enabled && r.custom == "")
// opened in this same moment (a submenu entered by ArrowRight): its rows
// are built as this settle closes, so the step waits for them
if (rows.length == 0) {
    if (this.shown && this.rowsOf(this.panel.body).length == 0 && (this.items ?? []).length > 0) afterSettle(() => this.step(d))
    return
    }
const i = rows.indexOf(this.activeRow)
this.activeRow = rows[i < 0 ? (d > 0 ? 0 : rows.length - 1) : (i + d + rows.length) % rows.length]
this.revealRow(this.activeRow)

if (r == null) return
if (r.sub) { this.enterSub(); return }
r.pickSelf()

if (r == null || !r.sub) return
r.openSelf()
if (this.child != null) this.stepIn(this.child)

if (!classroot.shown) return
if (classroot.subShown(classroot.child)) return   // the deeper menu handles
if (e.key == "ArrowDown") classroot.step(1)
else if (e.key == "ArrowUp") classroot.step(-1)
else if (e.key == "Enter") classroot.pickActive()
else if (e.key == "ArrowRight") classroot.enterSub()
else if (e.key == "ArrowLeft") { if (!classroot.isRoot) classroot.close() }

this.openId = "" + t.mid
this.menu.openFor(t)
// the menu self-raises, which lifts its full-app backdrop over the
// titles — but a tracking bar stays hot while a menu is open (that is
// what tracking is). Promote the row back above the backdrop; the
// panel drops below the bar, so nothing occludes visually.
this.row.raise()
// raise() is per parent: the menu is this bar's child, so it rose
// above the bar's row and nothing else. A sibling declared after the
// bar — a page's content, laid out under the chrome — would still
// paint over the dropped panel and take its clicks. The bar is chrome:
// while it drops a menu it belongs above its siblings, so it raises
// itself too. (A bar nested in a container that is itself under other
// content declares that container last — stacking is source order —
// or hosts its menu at the app layer, the Combobox idiom.)
this.raise()

const ms = this.menus || []
const i = ms.findIndex((m) => "" + m.id == this.openId)
if (i < 0 || ms.length < 2) return
const nid = "" + ms[(i + d + ms.length) % ms.length].id
const t = this.rowsOf().find((r) => "" + r.mid == nid)
if (t != null) this.openMenu(t)

if (!classroot.menu.shown) return
if (classroot.menu.subShown(classroot.menu.child)) return
if (e.key == "ArrowLeft") classroot.stepMenu(-1)
else if (e.key == "ArrowRight") { if (!classroot.hasSub(classroot.menu.activeRow)) classroot.stepMenu(1) }

if (this.disabled || e.repeat) return
if (e.key == "Enter" || e.key == " ") this.press()
else if (e.key == "ArrowDown" && this.menu != null) this.openMenu()

d.scale(this.unit, this.unit)
d.fillStyle = this.ink
d.strokeStyle = this.ink
d.lineWidth = this.weight / this.unit
d.lineCap = "round"
// The ring is drawn a touch smaller than the solid disc: a stroke straddles
// its path, so an outline at the filled radius reads as the larger mark.
d.beginPath()
d.arc(8, 8, classroot.solid ? 3.5 : 3.15, 0, Math.PI * 2, false)
if (classroot.solid) d.fill()
else d.stroke()
for (let i = 0; i < classroot.rays; i++) {
    const a = (i / classroot.rays) * Math.PI * 2
    const c = Math.cos(a), s = Math.sin(a)
    d.beginPath()
    d.moveTo(8 + c * 5.3, 8 + s * 5.3)
    d.lineTo(8 + c * 6.9, 8 + s * 6.9)
    d.stroke()
    }

const w = this.width, h = this.height
const Q = Math.PI / 2
const dist = Math.abs(this.x - this.tx) + Math.abs(this.y - this.ty) + Math.abs(this.width - this.tw) + Math.abs(this.height - this.th)
const small = Math.min(w, h) < 40
// By default the ring travels as a closed outline, source shape to
// destination shape — no bracket mode intervening. `provided("theme").focusSights
// = true` elects the sights rendition instead (data, not a code path):
// fully open in motion, arms sweeping shut inside the last 16px of
// settle.
const cov = this.$provided("theme").focusSights == true && !small ? Math.max(0.22, 1 - dist / 16) : 1
const lw = typeof this.$provided("theme").focusRingWidth == "number" ? this.$provided("theme").focusRingWidth : 3
// The indicator is one band or two, by data: `focusRingInnerWidth` > 0
// adds an inner stroke between the control and the outer one — the
// Redmond two-tone focus rectangle, black over white. Both passes are
// the same outline at different insets; the flight, the sights, and
// the silhouette machinery are shared, not forked.
const iw = typeof this.$provided("theme").focusRingInnerWidth == "number" ? this.$provided("theme").focusRingInnerWidth : 0
const pass = (ins, lwp, color) => {
    const r = Math.max(1, Math.min(this.rad - ins, Math.min(w, h) / 2 - ins))
    const ax = Math.max(0, ((w - 2 * ins) / 2 - r) * cov)      // horizontal arm length
    const ay = Math.max(0, ((h - 2 * ins) / 2 - r) * cov)      // vertical arm length
    d.strokeStyle = color
    d.lineWidth = lwp
    d.beginPath()
    // each corner: arc + arms, inset symmetrically
    d.moveTo(ins + r + ax, ins); d.lineTo(ins + r, ins); d.arc(ins + r, ins + r, r, -Q, Math.PI, true); d.lineTo(ins, ins + r + ay)
    d.moveTo(w - ins - r - ax, ins); d.lineTo(w - ins - r, ins); d.arc(w - ins - r, ins + r, r, -Q, 0); d.lineTo(w - ins, ins + r + ay)
    d.moveTo(w - ins, h - ins - r - ay); d.lineTo(w - ins, h - ins - r); d.arc(w - ins - r, h - ins - r, r, 0, Q); d.lineTo(w - ins - r - ax, h - ins)
    d.moveTo(ins + r + ax, h - ins); d.lineTo(ins + r, h - ins); d.arc(ins + r, h - ins - r, r, Q, Math.PI); d.lineTo(ins, h - ins - r - ay)
    d.stroke()
    }
pass(0, lw, typeof this.$provided("theme").focusRingColor == "number" ? this.$provided("theme").focusRingColor : this.$provided("theme").accent)
if (iw > 0) pass((lw + iw) / 2, iw, typeof this.$provided("theme").focusRingInnerColor == "number" ? this.$provided("theme").focusRingInnerColor : this.$provided("theme").surface)

if (g.root != this.root) return
// Travel with the target's scroller: the ring's surface re-hosts
// inside the scrolled container and positions in its content
// coordinates — the platform then carries ring and control
// together, zero lag, no per-scroll re-derive. A renderer without
// the ride keeps root-space reactive positioning.
const prev = (this)._lastTarget
const prevHome = (this)._lastHome
const hadHome = (this)._hasHome === true
const px = classroot.x
const py = classroot.y
const homed = classroot.travelWith(g.scroller)
const gx = homed ? g.homeX : g.x
const gy = homed ? g.homeY : g.y
// Crossing scroll homes (the bar's button → a control in the
// scrolled page): the flight must still fly. The ring's current
// position converts through root space into the destination
// home's coordinates — same painted spot, new numbers — and the
// springs then travel entirely within the new space (correct
// even if that pane scrolls mid-flight).
if (hadHome && prevHome != g.scroller) {
    const toRoot = prevHome == null || prevHome == this.root
        ? ({ x: px, y: py })
        : (() => { const o = prevHome.rootOrigin(); return ({ x: o.x + px - prevHome.scrollX, y: o.y + py - prevHome.scrollY }) })()
    const dst = !homed || g.scroller == this.root
        ? toRoot
        : (() => { const o = g.scroller.rootOrigin(); return ({ x: toRoot.x - o.x + g.scroller.scrollX, y: toRoot.y - o.y + g.scroller.scrollY }) })()
    classroot.x = dst.x
    classroot.y = dst.y
    }
const gap = typeof this.$provided("theme").focusRingGap == "number" ? this.$provided("theme").focusRingGap : 0
const lw = typeof this.$provided("theme").focusRingWidth == "number" ? this.$provided("theme").focusRingWidth : 3
const iw = typeof this.$provided("theme").focusRingInnerWidth == "number" ? this.$provided("theme").focusRingInnerWidth : 0
const off = gap + iw + lw / 2
// a traveled ring draws the content-space box (homeW/homeH/homeRad):
// any ancestor transform above the scroller reaches its surface
// through the platform, so frame-space extents would double-apply it
classroot.tx = gx - off; classroot.ty = gy - off
classroot.tw = (homed ? g.homeW : g.w) + 2 * off; classroot.th = (homed ? g.homeH : g.h) + 2 * off
classroot.trad = (homed ? g.homeRad : g.rad) + off
// Only a focus change flies. The same control moving under a resting
// ring — a dragged slider thumb, a reflow — takes the ring with it
// rigidly: the springs' targets just moved, so land them now. The
// discriminator is target identity (a handler-scratch expando — not
// reactive state, just the previous event's view for comparison).
;(this)._lastTarget = g.view
;(this)._lastHome = g.scroller
;(this)._hasHome = true
if (prev == g.view) classroot.snapTo()

if (v == null) { classroot.shown = false; return }
let n = v
for (; n != null && n.parent != null; n = n.parent) { }
// Another app on the page (an embedded preview) owns this target — its own
// ring indicates it; this one stands down rather than chase foreign coordinates.
if (n != this.root) { classroot.shown = false; return }
// Pointer focus: park silently — geometry current, ring hidden. The next
// keyboard flight departs from here (the just-clicked control).
if (!Focus.byKeyboard()) { classroot.shown = false; classroot.snapTo(); classroot.placed = true; return }
if (classroot.ringRole() == "off") { classroot.shown = false; return }
// No flight when: the ring has never been placed, the theme suppressed
// the flourish, or the role is rest-only (appear in place, stay).
if (!classroot.placed || this.$provided("theme").focusAnimate == false || !classroot.travelRole()) classroot.snapTo()
classroot.placed = true
classroot.shown = true
classroot.raise()     // chrome stays chrome: above whatever raised last (a Dialog, a Menu)
// idle fade only for the travel-only role — a resting ring persists
if (classroot.restRole()) { classroot.idle = false; return }
classroot.gen = classroot.gen + 1
const g2 = classroot.gen
classroot.idle = false
this.$afterDelay(1000, () => { if (classroot.gen == g2) classroot.idle = true })

// An interrupted drag (the browser took the finger for a page pan —
// a quick swipe over the title bar on a floored, panning desktop)
// must not leave the window displaced by the pre-take moves.
if (canceled) { this.wx = this.wx0; this.wy = this.wy0 }
this.dragging = false

const g = classroot.gutter + classroot.inset
const c = classroot.corner
const w = this.width
const h = this.height
const inL = px < g
const inR = px >= w - g
const inT = py < g
const inB = py >= h - g
if (!inL && !inR && !inT && !inB) {
    // The corner crescents. The band's inner cut is rounded
    // (ring, same bandR), so at each corner the band reaches
    // past the straight-line tests above: the sliver between
    // the straight boundary and the inner arc is hittable —
    // the cursor children already show a resize cursor there —
    // and a grab must do what the cursor promises. In-ring =
    // on the corner side of the arc's center and farther than
    // bandR from it; the zone then follows the same strips the
    // cursors use (corner square → diagonal, else the edge).
    const r = classroot.bandR
    const ox = (px < w / 2 ? g + r - px : px - (w - g - r))
    const oy = (py < h / 2 ? g + r - py : py - (h - g - r))
    if (ox > 0 && oy > 0 && ox * ox + oy * oy > r * r) {
        const chz = px < c ? "l" : px >= w - c ? "r" : ""
        const cvz = py < c ? "t" : py >= h - c ? "b" : ""
        return chz + cvz
    }
    return ""
}
let hz = inL ? "l" : inR ? "r" : (px < g + c ? "l" : px >= w - g - c ? "r" : "")
let vz = inT ? "t" : inB ? "b" : (py < g + c ? "t" : py >= h - g - c ? "b" : "")
if ((inL || inR) && !(py < g + c || py >= h - g - c)) vz = ""
if ((inT || inB) && !(px < g + c || px >= w - g - c)) hz = ""
return hz + vz

d.scale(this.width / 48, this.width / 48)
const a = classroot.ap
if (a != null) a.face(d)

const rootParts = rootPath == "" ? [] : rootPath.split("\n")
const parts = selPath == "" ? [] : selPath.split("\n")
const item = (n, p) => ({ name: "" + n.name, kind: "" + (n.kind || ""), label: "" + (n.label || ""),
    hasKids: (n.children != null && n.children.length > 0),
    path: "" + (n.path || ""), doc: "" + (n.doc || ""), preview: "" + (n.preview || ""),
    at: p.join("\n") })
let level = ((model || ({ })).browse) || []
// descend to the window's root folder — its children are the first column
for (let i = 0; i < rootParts.length; i = i + 1) {
    const n = level.find((x) => x.name == rootParts[i])
    if (n == null || n.children == null) return []
    level = n.children
}
// the selPath below the root drives the drill; `at` stays the absolute path
const drill = parts.slice(rootParts.length)
const cols = []
cols.push(({ items: level.map((n) => item(n, rootParts.concat([n.name]))), depth: 0 }))
for (let k = 0; k < drill.length; k = k + 1) {
    const chosen = level.find((n) => n.name == drill[k])
    if (chosen == null) break
    const prefix = rootParts.concat(drill.slice(0, k + 1))
    if (chosen.children != null && chosen.children.length > 0) {
        level = chosen.children
        cols.push(({ items: level.map((n) => item(n, prefix.concat([n.name]))), depth: cols.length }))
    } else {
        cols.push(({ leaf: item(chosen, prefix), depth: cols.length }))
        break
    }
}
return cols

const d = "" + (leaf.doc || ""), p = "" + (leaf.path || "")
if (d != "") { this.root.launcher.openDoc(d, "" + leaf.name, v); return }
if (p != "") this.root.launcher.openViewer("../../" + p, v)

d.scale(this.width / 48, this.width / 48)
const a = classroot.ap
if (a != null) a.face(d)

// the map itself, edge to edge like the calendar's page: one large cap
// and its neighbours in the day's two colours (the system green and
// red, a deeper shade for smaller moves), the plate's corners
// rounding it and its dark showing only in the hairline gaps
const up = 0x34C759, upLow = 0x248A3D, down = 0xFF453A, downLow = 0xC0352C
const tile = (c, x, y, w, h) => { d.fillStyle = c; d.fillRect(x, y, w, h) }
tile(up, 0, 0, 27, 30)                   // the giant, top left
tile(downLow, 0, 30.8, 15, 17.2)
tile(upLow, 15.8, 30.8, 11.2, 17.2)
tile(up, 27.8, 0, 20.2, 13)
tile(down, 27.8, 13.8, 20.2, 10.2)
tile(upLow, 27.8, 24.8, 11, 23.2)
tile(down, 39.6, 24.8, 8.4, 11.4)
tile(upLow, 39.6, 37, 8.4, 11)
// the light the other plates have: a touch brighter at the top, deeper at the foot
const shade = d.createLinearGradient(0, 0, 0, 48)
shade.addColorStop(0, "rgba(255,255,255,0.16)")
shade.addColorStop(1, "rgba(0,0,0,0.18)")
d.fillStyle = shade
d.fillRect(0, 0, 48, 48)

const ws = this.recs()
let at = ws.length
for (let i = 0; i < ws.length; i++) if (ws[i].mini == true) { at = i; break }
this.list.insert(["wins"], at, rec)

if (w == null || w.recId == "" || this.isMin(w)) return
const ws = this.recs()
const from = ws.findIndex((r) => r.id == w.recId)
if (from < 0) return
const rest = ws.filter((r) => r.id != w.recId)
let to = rest.length
for (let i = 0; i < rest.length; i++) if (rest[i].mini == true) { to = i; break }
this.list.move(["wins"], from, to)

const i = this.idxOf(id)
if (i < 0) return
const ws = this.recs()
this.list.set(["wins", i], ({ ...(ws[i]), ...(p) }))

const doomed = this.windows().filter((w) => this.appOf(w) == a)
for (const w of doomed) this.closeWin(w)
a.running = false

this.root.dockDismiss()
const live = this.windows().filter((w) => this.appOf(w) == a && !this.isPlain(w) && !this.isMin(w))
if (live.length > 0) { for (const w of live) this.focusWin(w); return }
// nothing up but something in the dock: restore the most recent tile
const mins = this.miniList().filter((w) => this.appOf(w) == a)
if (mins.length > 0) { this.restoreMini(mins[mins.length - 1]); return }
open()

if (w == null || this.isPlain(w) || this.isMin(w)) return
// capture what the dock needs while the window is parked — label and
